import copy
import hashlib
import hmac


class AuthenticationError(Exception):
    pass


class PermitDesk:
    def __init__(self, records):
        if not isinstance(records, list):
            raise TypeError("records must be a list")
        self._records = {}
        for record in records:
            if not isinstance(record, dict):
                raise TypeError("records must contain dictionaries")
            if set(record) != {"identifier", "pin_hash", "profile"}:
                raise ValueError("record fields are invalid")
            identifier = record["identifier"]
            pin_hash = record["pin_hash"]
            profile = record["profile"]
            if not isinstance(identifier, str) or not isinstance(pin_hash, str):
                raise TypeError("identifier and pin_hash must be strings")
            if not isinstance(profile, dict):
                raise TypeError("profile must be a dictionary")
            if not identifier or not pin_hash or identifier in self._records:
                raise ValueError("record content is invalid")
            self._records[identifier] = copy.deepcopy(record)
        self._login_number = 0
        self._renew_access_number = 0
        self._refresh_tokens = set()

    def login(self, identifier, pin):
        if not isinstance(identifier, str) or not isinstance(pin, str):
            raise TypeError("identifier and pin must be strings")
        record = self._records.get(identifier)
        digest = hashlib.sha256(pin.encode("utf-8")).hexdigest()
        if record is None or not hmac.compare_digest(digest, record["pin_hash"].lower()):
            raise AuthenticationError("invalid credentials")
        self._login_number += 1
        refresh = f"R{self._login_number}"
        self._refresh_tokens.add(refresh)
        return {"access": f"A{self._login_number}", "refresh": refresh,
                "profile": record["profile"]}

    def renew(self, refresh):
        if not isinstance(refresh, str) or refresh not in self._refresh_tokens:
            raise AuthenticationError("invalid refresh token")
        self._renew_access_number += 1
        return f"A{self._renew_access_number}"

